package backend

import "strconv"

const Endpoint = "GET /items?cursor={cursor}&limit={limit}"

type Item struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type ItemsPage struct {
	Items      []Item `json:"items"`
	NextCursor *string `json:"next_cursor"`
}

var items = []Item{
	{ID: "1", Name: "first"},
	{ID: "2", Name: "second"},
	{ID: "3", Name: "third"},
}

func FetchItems(cursor string, limit int) ItemsPage {
	start := 0
	if cursor != "" {
		if decoded, err := strconv.Atoi(cursor); err == nil && decoded >= 0 && decoded <= len(items) {
			start = decoded
		}
	}
	if limit <= 0 {
		limit = 20
	}
	end := start + limit
	if end > len(items) {
		end = len(items)
	}

	page := ItemsPage{Items: items[start:end]}
	if end < len(items) {
		next := strconv.Itoa(end)
		page.NextCursor = &next
	}
	return page
}

